    magneticDomains:{title:'University of Tennessee · Magnetic materials',url:'https://labs.phys.utk.edu/mbreinig/phys222core/modules/m4/magnetic%20materials.html',note:'מקור המגנטיות האלקטרונית, צימוד חילוף ותחומים מגנטיים; באנגלית.'},
